
"use client";

import { useState, useEffect, useRef } from "react";
import { type SmartRevisionPlannerOutput } from "@/ai/flows/smart-revision-planner";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Lightbulb, BookCheck, AlertTriangle, Loader2, PlusCircle, Filter, Clock, Play, Pause, RefreshCw, Timer as TimerIcon, Hourglass } from "lucide-react";
import { getRevisionPlan } from "./actions";
import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/utils";

// Mock data for Organize and Schedule tabs
const mockMaterials = [
  { id: 1, subject: 'Physics', topic: 'Newton\'s Laws', nextReview: '2024-09-15', status: 'Due' },
  { id: 2, subject: 'Chemistry', topic: 'Organic Compounds', nextReview: '2024-09-18', status: 'Upcoming' },
  { id: 3, subject: 'Math', topic: 'Calculus II', nextReview: '2024-09-12', status: 'Due' },
  { id: 4, subject: 'History', topic: 'The Renaissance', nextReview: '2024-09-22', status: 'Upcoming' },
];

type TimerTechnique = "pomodoro" | "52-17" | "ultradian" | "flowtime";
type TimerPhase = 'focus' | 'short' | 'long';

const techniques = {
  pomodoro: {
    name: "Pomodoro",
    description: "Work in 25-min sprints with short breaks. Good for breaking down large tasks.",
    phases: { focus: 25 * 60, short: 5 * 60, long: 15 * 60 }
  },
  "52-17": {
    name: "52-17 Rule",
    description: "A highly productive cycle of 52 minutes of work followed by a 17-minute break.",
    phases: { focus: 52 * 60, short: 17 * 60, long: 17 * 60 }
  },
  ultradian: {
    name: "Ultradian Rhythm",
    description: "Longer 90-minute focus blocks followed by a substantial 20-30 minute rest.",
    phases: { focus: 90 * 60, short: 20 * 60, long: 30 * 60 }
  },
  flowtime: {
    name: "Flowtime",
    description: "A flexible stopwatch to track your focus sessions without a fixed timer.",
    phases: { focus: 0, short: 0, long: 0 }
  }
};

export default function PlannerPage() {
  const [plan, setPlan] = useState<SmartRevisionPlannerOutput | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Timer state
  const [technique, setTechnique] = useState<TimerTechnique>("pomodoro");
  const [timer, setTimer] = useState(techniques.pomodoro.phases.focus);
  const [isTimerActive, setIsTimerActive] = useState(false);
  const [timerPhase, setTimerPhase] = useState<TimerPhase>('focus');
  const timerIntervalRef = useRef<NodeJS.Timeout | null>(null);

  useEffect(() => {
    if (isTimerActive && timer > 0) {
      timerIntervalRef.current = setInterval(() => {
        setTimer(seconds => seconds - 1);
      }, 1000);
    } else if (timer === 0 && isTimerActive) {
      setIsTimerActive(false);
      // Here you could add a notification that the session is over
    }
    return () => {
      if (timerIntervalRef.current) clearInterval(timerIntervalRef.current);
    };
  }, [isTimerActive, timer]);

  const handleTechniqueChange = (value: TimerTechnique) => {
    setTechnique(value);
    setIsTimerActive(false);
    setTimerPhase('focus');
    setTimer(techniques[value].phases.focus);
  };

  const setPhase = (phase: TimerPhase) => {
    setTimerPhase(phase);
    setIsTimerActive(false);
    setTimer(techniques[technique].phases[phase]);
  };

  const toggleTimer = () => setIsTimerActive(!isTimerActive);
  const resetTimer = () => {
    setIsTimerActive(false);
    setTimer(techniques[technique].phases[timerPhase]);
  };
  
  const formatTime = (seconds: number) => {
    const minutes = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${String(minutes).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;
  };

  const handleGeneratePlan = async () => {
    setLoading(true);
    setError(null);
    setPlan(null);
    const result = await getRevisionPlan();
    if (result) {
      setPlan(result);
    } else {
      setError("Failed to generate a revision plan. Please try again.");
    }
    setLoading(false);
  };

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-3xl font-bold font-headline">My Planner</h1>
        <p className="text-muted-foreground">
          Your central hub for organizing, scheduling, and tackling your studies.
        </p>
      </div>

      <Tabs defaultValue="add" className="w-full">
        <TabsList className="grid w-full grid-cols-4">
          <TabsTrigger value="add">Add Data</TabsTrigger>
          <TabsTrigger value="organize">Organize</TabsTrigger>
          <TabsTrigger value="schedule">Schedule</TabsTrigger>
          <TabsTrigger value="timer">Focus Timer</TabsTrigger>
        </TabsList>

        {/* Add Data Tab */}
        <TabsContent value="add" className="mt-6">
          <Card>
            <CardHeader>
              <CardTitle>Add New Study Material</CardTitle>
              <CardDescription>Input your raw study information. This becomes the foundation for your flashcards and mind maps.</CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
               <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                 <div className="space-y-2">
                    <Label htmlFor="subject">Subject</Label>
                    <Input id="subject" placeholder="e.g., Physics" />
                  </div>
                   <div className="space-y-2">
                    <Label htmlFor="topic">Topic</Label>
                    <Input id="topic" placeholder="e.g., Newton's Laws of Motion" />
                  </div>
               </div>
               <div className="space-y-2">
                <Label htmlFor="notes">Detailed Notes</Label>
                <Textarea id="notes" placeholder="Add your notes, key concepts, and summaries here..." rows={6} />
              </div>
               <div className="space-y-2">
                <Label htmlFor="links">Reference Links</Label>
                <Input id="links" placeholder="https://example.com" />
              </div>
              <div className="space-y-2">
                <Label htmlFor="file-upload">File Upload</Label>
                <Input id="file-upload" type="file" />
                <p className="text-xs text-muted-foreground">Upload relevant documents, diagrams, or lecture slides.</p>
              </div>
              <Button>
                <PlusCircle className="mr-2 h-4 w-4"/>
                Add Material
              </Button>
            </CardContent>
          </Card>
        </TabsContent>

        {/* Organize Tab */}
        <TabsContent value="organize" className="mt-6">
          <Card>
            <CardHeader>
              <CardTitle>Your Study Library</CardTitle>
              <CardDescription>All your study materials in one place. Filter and sort to manage your knowledge base.</CardDescription>
            </CardHeader>
            <CardContent>
              <div className="flex flex-col md:flex-row gap-4 mb-6">
                <Input placeholder="Search topics..." className="flex-1" />
                <Select>
                  <SelectTrigger className="w-full md:w-[180px]">
                    <SelectValue placeholder="Filter by subject" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all">All Subjects</SelectItem>
                    <SelectItem value="physics">Physics</SelectItem>
                    <SelectItem value="chemistry">Chemistry</SelectItem>
                    <SelectItem value="math">Math</SelectItem>
                     <SelectItem value="history">History</SelectItem>
                  </SelectContent>
                </Select>
                 <Button variant="outline"><Filter className="mr-2 h-4 w-4" /> Apply</Button>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {mockMaterials.map(material => (
                  <Card key={material.id}>
                    <CardHeader>
                      <div className="flex justify-between items-start">
                        <div>
                          <CardTitle className="text-lg">{material.topic}</CardTitle>
                          <CardDescription>{material.subject}</CardDescription>
                        </div>
                         <Badge variant={material.status === 'Due' ? 'destructive' : 'secondary'}>{material.status}</Badge>
                      </div>
                    </CardHeader>
                    <CardContent>
                      <p className="text-sm text-muted-foreground">Next review: {material.nextReview}</p>
                      <Button variant="link" className="p-0 h-auto mt-2">View Details</Button>
                    </CardContent>
                  </Card>
                ))}
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        {/* Schedule Tab */}
        <TabsContent value="schedule" className="mt-6">
          <div className="grid gap-6 lg:grid-cols-3">
            <div className="lg:col-span-2 space-y-4">
              <h2 className="text-2xl font-semibold font-headline">AI Generated Plan</h2>
               <Card>
                <CardHeader>
                  <CardTitle>Today's AI Suggestions</CardTitle>
                  <CardDescription>Click the button below to generate a personalized study plan for today.</CardDescription>
                </CardHeader>
                <CardContent>
                  <Button onClick={handleGeneratePlan} disabled={loading}>
                    {loading ? (
                      <>
                        <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                        Generating...
                      </>
                    ) : (
                      "Generate Today's Plan"
                    )}
                  </Button>
                </CardContent>
              </Card>

              {error && (
                 <Card className="border-destructive">
                    <CardHeader className="flex flex-row items-center gap-4">
                        <AlertTriangle className="h-8 w-8 text-destructive" />
                        <div>
                            <CardTitle className="text-destructive">An Error Occurred</CardTitle>
                            <CardDescription>{error}</CardDescription>
                        </div>
                    </CardHeader>
                </Card>
              )}

              {plan && plan.revisionList.length > 0 && (
                  <ul className="space-y-4">
                    {plan.revisionList.map((task, index) => (
                      <li key={index}>
                        <Card className="hover:border-primary transition-colors">
                          <CardHeader className="flex flex-row items-start justify-between">
                            <div>
                              <CardTitle>{task.topic}</CardTitle>
                              <CardDescription className="flex items-center gap-2 mt-1">
                                <Lightbulb className="w-4 h-4 text-amber-500" />
                                <span>{task.reason}</span>
                              </CardDescription>
                            </div>
                            <Button size="sm" variant="outline">
                              <BookCheck className="mr-2 h-4 w-4" />
                              Revise Now
                            </Button>
                          </CardHeader>
                        </Card>
                      </li>
                    ))}
                  </ul>
              )}
               {plan && plan.revisionList.length === 0 && (
                 <Card>
                    <CardHeader>
                        <CardTitle>All Caught Up!</CardTitle>
                        <CardDescription>No priority revisions for today. Feel free to explore new topics!</CardDescription>
                    </CardHeader>
                </Card>
              )}
            </div>
            <div className="space-y-4">
              <h2 className="text-2xl font-semibold font-headline">Upcoming Deadlines</h2>
              <Card>
                  <CardContent className="pt-6 space-y-4">
                      {mockMaterials.filter(m => m.status === 'Due').map(item => (
                        <div key={item.id} className="flex justify-between items-center p-3 bg-muted rounded-md">
                            <div>
                                <p className="font-semibold">{item.topic}</p>
                                <p className="text-sm text-muted-foreground">{item.subject}</p>
                            </div>
                             <Badge variant="destructive">{item.nextReview}</Badge>
                        </div>
                      ))}
                  </CardContent>
              </Card>
            </div>
          </div>
        </TabsContent>

        {/* Timer Tab */}
        <TabsContent value="timer" className="mt-6">
          <Card className="max-w-md mx-auto">
            <CardHeader className="text-center">
              <div className="flex justify-center items-center gap-4 mb-4">
                 <Hourglass />
                 <Select value={technique} onValueChange={(v) => handleTechniqueChange(v as TimerTechnique)}>
                   <SelectTrigger className="w-[200px] text-lg font-semibold">
                      <SelectValue placeholder="Select a technique" />
                   </SelectTrigger>
                   <SelectContent>
                      <SelectItem value="pomodoro">Pomodoro</SelectItem>
                      <SelectItem value="52-17">52-17 Rule</SelectItem>
                      <SelectItem value="ultradian">Ultradian Rhythm</SelectItem>
                      <SelectItem value="flowtime">Flowtime</SelectItem>
                   </SelectContent>
                 </Select>
              </div>
              <CardDescription className="text-xs h-8 transition-all duration-300">
                {techniques[technique].description}
              </CardDescription>
            </CardHeader>
            <CardContent className="flex flex-col items-center space-y-6">
                {technique !== "flowtime" && (
                  <div className="space-x-2">
                      <Button variant={timerPhase === 'focus' ? 'default' : 'secondary'} onClick={() => setPhase('focus')}>Focus</Button>
                      <Button variant={timerPhase === 'short' ? 'default' : 'secondary'} onClick={() => setPhase('short')}>Short Break</Button>
                      <Button variant={timerPhase === 'long' ? 'default' : 'secondary'} onClick={() => setPhase('long')}>Long Break</Button>
                  </div>
                )}
                <div className={cn(
                  "text-8xl font-bold font-mono transition-colors duration-300",
                   timerPhase === 'focus' ? 'text-primary' : 'text-green-500'
                )}>
                    {formatTime(timer)}
                </div>
                <div className="flex items-center gap-4">
                    <Button size="lg" onClick={toggleTimer} className="w-32">
                        {isTimerActive ? <Pause className="mr-2"/> : <Play className="mr-2"/>}
                        {isTimerActive ? 'Pause' : 'Start'}
                    </Button>
                     <Button size="lg" variant="outline" onClick={resetTimer}>
                        <RefreshCw className="mr-2"/>
                        Reset
                    </Button>
                </div>
            </CardContent>
          </Card>
        </TabsContent>

      </Tabs>
    </div>
  );
}
